import path from 'node:path';
import { GrammyError, InlineKeyboard, InputFile } from 'grammy';
import { bot } from '../bot/index.js';
import { config } from '../config.js';
import { User, Broadcast } from '../models/index.js';
import { ApiError } from './orders.js';
import { deleteUpload } from '../api/files.js';

// ~25 messages per second (Telegram allows about 30 per second)
export const SEND_DELAY_MS = 40;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const OPEN_APP = { om: '🚘 Appii bani', am: '🚘 መተግበሪያውን ክፈት', en: '🚘 Open app' };

// Sends ONE announcement to ONE chat. Returns the photo's file_id (so the photo is uploaded only once).
async function sendTo(chatId, lang, { text, photo }) {
  const extra = config.webAppUrl.startsWith('https://')
    ? { reply_markup: new InlineKeyboard().webApp(OPEN_APP[lang] || OPEN_APP.en, config.webAppUrl) }
    : {};

  if (!photo) {
    await bot.api.sendMessage(chatId, text, extra);
    return null;
  }
  // a photo caption can hold only 1024 characters; longer text goes as a second message
  if (text.length <= 1024) {
    const m = await bot.api.sendPhoto(chatId, photo, { ...(text ? { caption: text } : {}), ...extra });
    return m.photo.at(-1).file_id;
  }
  const m = await bot.api.sendPhoto(chatId, photo);
  await bot.api.sendMessage(chatId, text, extra);
  return m.photo.at(-1).file_id;
}

// returns { ok, fileId } | { blocked } | { failed, error }
async function attempt(chatId, lang, content, retried = false) {
  try {
    return { ok: true, fileId: await sendTo(chatId, lang, content) };
  } catch (e) {
    if (e instanceof GrammyError) {
      if (e.error_code === 403 || (e.error_code === 400 && /chat not found/i.test(e.description))) {
        return { blocked: true };
      }
      if (e.error_code === 429 && !retried) {
        await sleep(((e.parameters?.retry_after ?? 5) + 0.5) * 1000);
        return attempt(chatId, lang, content, true);
      }
    }
    return { failed: true, error: e.message };
  }
}

const localFile = (url) => new InputFile(path.join(config.uploadDir, url.replace('/uploads/', '')));

// Sends the announcement only to the admin who is writing it
export async function sendTest({ text, photoUrl, adminId }) {
  if (!bot) throw new ApiError(503, 'bot_off');
  const admin = await User.findOne({ telegramId: adminId }).select('language');
  const r = await attempt(adminId, admin?.language, { text, photo: photoUrl ? localFile(photoUrl) : null });
  if (!r.ok) throw new ApiError(502, r.blocked ? 'admin_blocked_bot' : 'telegram_error', { detail: r.error });
}

export async function startBroadcast({ text, photoUrl, by }) {
  if (!bot) throw new ApiError(503, 'bot_off');
  if (await Broadcast.exists({ status: 'SENDING' })) throw new ApiError(409, 'broadcast_running');

  const users = await User.find().select('telegramId language').lean();
  if (!users.length) throw new ApiError(409, 'no_users');
  const b = await Broadcast.create({ text, hasPhoto: !!photoUrl, total: users.length, by });

  run(b._id, users, text, photoUrl).catch((e) => console.error('Broadcast crashed:', e.message));
  return b;
}

async function run(id, users, text, photoUrl) {
  let photo = photoUrl ? localFile(photoUrl) : null;
  let sent = 0, blocked = 0, failed = 0, n = 0;
  const save = () => Broadcast.updateOne({ _id: id }, { sent, blocked, failed });

  for (const u of users) {
    const r = await attempt(u.telegramId, u.language, { text, photo });
    if (r.ok) {
      sent++;
      if (r.fileId) photo = r.fileId; // later users get the photo from Telegram's servers
    } else if (r.blocked) blocked++;
    else failed++;

    if (++n % 20 === 0) await save();
    await sleep(SEND_DELAY_MS);
  }
  await save();
  await Broadcast.updateOne({ _id: id }, { status: 'DONE' });
  if (photoUrl) await deleteUpload(photoUrl);
}
